mapper.sql:
FROM merchant m
JOIN merchant_store s ON s.merchant_id=m.id AND s.id=#{storeId}
JOIN merchant_member mb ON mb.merchant_id=m.id AND mb.user_id=#{userId}
LEFT JOIN merchant_member_store_grant g ON g.member_id=mb.id AND g.store_id=s.id
LEFT JOIN merchant_staff ms ON ms.id=g.staff_id
WHERE m.id=#{merchantId}

mapper.select:
SELECT action_code FROM merchant_member_store_action
WHERE member_id=#{memberId} AND store_id=#{storeId}
ORDER BY action_code ASC

SELECT action_code FROM merchant_member_store_action
WHERE member_id=#{memberId} AND store_id=#{storeId}
ORDER BY action_code ASC FOR UPDATE
